import{_ as e,c as t,o as r,ae as o}from"./chunks/framework.CHDT0Kbg.js";const p=JSON.parse('{"title":"常见问题排查","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/troubleshooting.md","filePath":"zh-CN/guide/troubleshooting.md","lastUpdated":1795170900000}'),i={name:"zh-CN/guide/troubleshooting.md"};function l(h,a,n,s,d,u){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="常见问题排查" tabindex="-1">常见问题排查 <a class="header-anchor" href="#常见问题排查" aria-label="Permalink to &quot;常见问题排查&quot;">​</a></h1><p>遇到问题时可以试试这些办法。</p><h2 id="网页打不开" tabindex="-1">网页打不开 <a class="header-anchor" href="#网页打不开" aria-label="Permalink to &quot;网页打不开&quot;">​</a></h2><ul><li>先确认其他网站能否打开，再按 ⌘R 刷新。</li><li>如果开了广告拦截规则，先暂停一下，看看是不是拦了这个网站。</li><li>用无痕窗口（⌘⇧N）试试。如果无痕下正常，可在设置里清除该网站的 Cookie。</li></ul><h2 id="下载卡住或不完整" tabindex="-1">下载卡住或不完整 <a class="header-anchor" href="#下载卡住或不完整" aria-label="Permalink to &quot;下载卡住或不完整&quot;">​</a></h2><ul><li>打开下载面板，暂停后重试。</li><li>从网页保存的视频如果失败，先删除不完整的文件再试。分段视频会合成一个 MP4，合成失败时原始分片会留在下载目录。</li></ul><h2 id="书签没导入成功" tabindex="-1">书签没导入成功 <a class="header-anchor" href="#书签没导入成功" aria-label="Permalink to &quot;书签没导入成功&quot;">​</a></h2><p>先在旧浏览器里把书签导出成 HTML 文件，再在 Persim 的书签管理器里选择「导入 HTML」。文件夹和重复链接会自动处理。</p><h2 id="检测不到视频" tabindex="-1">检测不到视频 <a class="header-anchor" href="#检测不到视频" aria-label="Permalink to &quot;检测不到视频&quot;">​</a></h2><p>不是每个网站都能直接保存视频。在目标页面打开媒体面板看看；如果没有列出，说明该站点的播放方式不支持直接保存。</p><h2 id="浏览器变慢" tabindex="-1">浏览器变慢 <a class="header-anchor" href="#浏览器变慢" aria-label="Permalink to &quot;浏览器变慢&quot;">​</a></h2><p>关掉不用的标签页，或停用不再需要的广告拦截订阅。站点权限可以在设置里查看。</p><h2 id="还是解决不了" tabindex="-1">还是解决不了 <a class="header-anchor" href="#还是解决不了" aria-label="Permalink to &quot;还是解决不了&quot;">​</a></h2><p>发邮件到 <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>，说明你在做什么，最好附一张截图。</p>',14)])])}const m=e(i,[["render",l]]);export{p as __pageData,m as default};
